import json,re
_W=re.compile(r'[A-Za-z0-9_]+')
def toks(s): return frozenset(_W.findall((s or '').lower()))
def jac(a,b):
    if not a and not b: return 1.0
    if not a or not b: return 0.0
    return len(a&b)/len(a|b)
def txt(msg):
    c=msg.get('content')
    if isinstance(c,list): return ' '.join(str(x.get('text','')) for x in c if isinstance(x,dict))
    return str(c)
def runs(fn,thr=0.85,mode='anchor'):
    m=json.load(open(fn))
    asts=[toks(txt(x)) for x in m if x.get('role')=='assistant']
    asts=[a for a in asts if len(a)>=5]
    # anchor
    anch=None;run=0;maxr=0
    for a in asts:
        if anch is not None and jac(anch,a)>=thr: run+=1
        else: anch=a; run=1
        maxr=max(maxr,run)
    # sliding (vs previous)
    prev=None;run2=0;maxr2=0
    for a in asts:
        if prev is not None and jac(prev,a)>=thr: run2+=1
        else: run2=1
        prev=a; maxr2=max(maxr2,run2)
    return maxr,maxr2,len(asts)
for t in ['task_001044_45c70cf1','task_001465_aa3ed3f8','task_000032_3fb303f6','task_001201_1340f4e2','task_001028_5bc8bc70','task_000438_fee5a792','task_002138_2e85672e','task_000761_072f9e93']:
    a,s,n=runs(t+'.messages.json')
